     1→# ABOUTME: Exception class for type-related errors in the Chalk type system
     2→# ABOUTME: Provides detailed, user-friendly error messages for type mismatches and coercion failures
     3→
     4→use 5.042;
     5→use experimental qw(class);
     6→
     7→# Helper functions for creating type exceptions
     8→
     9→sub type_coercion_error($source_type, $target_type, $value = undef, $context = undef) {
    10→    my $msg = "Cannot coerce value from " . $source_type->name() . " to " . $target_type->name();
    11→    return Chalk::Type::Exception->new(
    12→        message => $msg,
    13→        source_type => $source_type,
    14→        target_type => $target_type,
    15→        value => $value,
    16→        context => $context
    17→    );
    18→}
    19→
    20→sub type_mismatch_error($expected_type, $actual_type, $context = undef) {
    21→    my $msg = "Type mismatch: expected " . $expected_type->name() . ", got " . $actual_type->name();
    22→    return Chalk::Type::Exception->new(
    23→        message => $msg,
    24→        source_type => $actual_type,
    25→        target_type => $expected_type,
    26→        context => $context
    27→    );
    28→}
    29→
    30→sub information_loss_warning($source_type, $target_type, $value, $context = undef) {
    31→    my $msg = "Warning: information loss in coercion from " .
    32→              $source_type->name() . " to " . $target_type->name();
    33→
    34→    if (defined($value)) {
    35→        my $value_str = defined($value) ? "'$value'" : 'undef';
    36→        $msg .= " (value: $value_str)";
    37→    }
    38→
    39→    if (defined($context)) {
    40→        $msg .= " in context: $context";
    41→    }
    42→
    43→    return $msg;
    44→}
    45→
    46→sub invalid_list_assignment_error($target_sigil) {
    47→    my $msg = "Cannot assign List to variable with sigil '$target_sigil'. " . "List can only be assigned to arrays (\@) or hashes (%)";
    48→    return Chalk::Type::Exception->new(
    49→        message => $msg,
    50→        context => "list assignment"
    51→    );
    52→}
    53→
    54→sub membership_failure_error($type, $value, $reason = undef) {
    55→    my $msg = "Value does not belong to type " . $type->name();
    56→
    57→    if (defined($reason)) {
    58→        $msg .= ": $reason";
    59→    }
    60→
    61→    return Chalk::Type::Exception->new(
    62→        message => $msg,
    63→        target_type => $type,
    64→        value => $value,
    65→        context => "type membership check"
    66→    );
    67→}
    68→
    69→class Chalk::Type::Exception {
    70→    field $message :param :reader;
    71→    field $source_type :param :reader = undef;
    72→    field $target_type :param :reader = undef;
    73→    field $value :param :reader = undef;
    74→    field $context :param :reader = undef;
    75→
    76→    method as_string() {
    77→        my $msg = $message;
    78→
    79→        if (defined($source_type) && defined($target_type)) {
    80→            $msg .= "\n  Source type: " . $source_type->name();
    81→            $msg .= "\n  Target type: " . $target_type->name();
    82→        }
    83→
    84→        if (defined($value)) {
    85→            my $value_str = defined($value) ? "'$value'" : 'undef';
    86→            $msg .= "\n  Value: $value_str";
    87→        }
    88→
    89→        if (defined($context)) {
    90→            $msg .= "\n  Context: $context";
    91→        }
    92→
    93→        return $msg;
    94→    }
    95→
    96→    method throw() {
    97→        die $self->as_string();
    98→    }
    99→}
   100→
   101→1;
   102→

